/*************************************************************************************************************************************
--
-- File Name    : H264_Encoder.v 
-- Description  : The IP compresses the video as per H.264 standard by using I and P frames. AXI4L to configure the registers.
				  The IP expects the input in YUV422 format and implements compression in YUV420 format.

-- COPYRIGHT 2024 BY MICROCHIP 
-- THE INFORMATION CONTAINED IN THIS DOCUMENT IS SUBJECT TO LICENSING RESTRICTIONS 
-- FROM MICROCHIP CORP.  IF YOU ARE NOT IN POSSESSION OF WRITTEN AUTHORIZATION FROM 
-- MICROCHIP FOR USE OF THIS FILE, THEN THE FILE SHOULD BE IMMEDIATELY DESTROYED AND 
-- NO BACK-UP OF THE FILE SHOULD BE MADE. 
--
--*************************************************************************************************************************************/
`timescale 1ns/1ps
module H264_Encoder#(
   parameter G_SLICES = 1,
   parameter G_P_FRM  = 0,
   parameter G_4K_EN  = 0, //1 slice when it is 0
   parameter G_16x16_INTRA_PRED = 0, //for I only frames
   parameter G_AXI4L  = 0,
   parameter G_DW 	  = 8, //only 8 is supported
   parameter G_DDR_AXI_DW = 512,
   parameter G_FRM_GAP    = 0  , //0 - 16MB, 1 - 32MB,
   parameter G_HMAX       = 3840,//change only for sim  432,//
   parameter G_VMAX 	  = 2160, //change only for sim  256//
   
   //register reset values   
   parameter G_HRES     = 16'd1920,//should be multiples of 16
   parameter G_VRES     = 16'd1072,//should be multiples of 16
   parameter G_QFACTOR  = 6'h1E, //1 to 51	
   parameter G_SKIP_TH  = 16'd512,	
   parameter G_P_CNT    = 8'd16,	
   parameter G_I_FORCE  = 1'b0,	
   parameter G_LINE_GAP = 16'h2000	
   )
 (    
   input              PIX_CLK_I,
   input              DDR_CLK_I,
   input              RESET_N,
   input              ENABLE_I,
   input  [15:0]      VRES_I,
   input  [15:0]      HRES_I,
   input  [15:0]      SKIP_THRESHOLD_I,
   input  [5:0]       QP_I,
   input  [7:0]       P_COUNT_I,
   input              I_FORCE_I,
   input              DATA_VALID_I,
   input  [G_DW-1:0]  DATA_Y_I,
   input  [G_DW-1:0]  DATA_C_I,
   input              FRAME_START_I,     // must be before frame start
   input  [15:0]      DDR_LINE_GAP_I,
   input  [7-G_FRM_GAP : 0] R_FRAME_START_ADDR_I,   
   input  [7-G_FRM_GAP : 0] W_FRAME_START_ADDR_I,
   
   //Arbiter bus 0
   input [G_DDR_AXI_DW - 1 : 0] RDATA0_I,
   input              RVALID0_I,
   input              ARREADY0_I,
   input              BUSER0_I,
   output [31 : 0]    ARADDR0_O,
   output             ARVALID0_O,
   output [7:0]       ARSIZE0_O,
   
   //Arbiter bus 1
   input [G_DDR_AXI_DW - 1 : 0] RDATA1_I,
   input              RVALID1_I,
   input              ARREADY1_I,
   input              BUSER1_I,
   output [31 : 0]    ARADDR1_O,
   output             ARVALID1_O,
   output [7:0]       ARSIZE1_O,
   
   //Arbiter bus 2
   input [G_DDR_AXI_DW - 1 : 0] RDATA2_I,
   input              RVALID2_I,
   input              ARREADY2_I,
   input              BUSER2_I,
   output [31 : 0]    ARADDR2_O,
   output             ARVALID2_O,
   output [7:0]       ARSIZE2_O,
   
   //Arbiter bus 3
   input [G_DDR_AXI_DW - 1 : 0] RDATA3_I,
   input              RVALID3_I,
   input              ARREADY3_I,
   input              BUSER3_I,
   output [31 : 0]    ARADDR3_O,
   output             ARVALID3_O,
   output [7:0]       ARSIZE3_O,
   
   //Arbiter bus 4
   input [G_DDR_AXI_DW - 1 : 0] RDATA4_I,
   input              RVALID4_I,
   input              ARREADY4_I,
   input              BUSER4_I,
   output [31 : 0]    ARADDR4_O,
   output             ARVALID4_O,
   output [7:0]       ARSIZE4_O,
   
   //Arbiter bus 5
   input [G_DDR_AXI_DW - 1 : 0] RDATA5_I,
   input              RVALID5_I,
   input              ARREADY5_I,
   input              BUSER5_I,
   output [31 : 0]    ARADDR5_O,
   output             ARVALID5_O,
   output [7:0]       ARSIZE5_O,
   
   //Arbiter bus 6
   input [G_DDR_AXI_DW - 1 : 0] RDATA6_I,
   input              RVALID6_I,
   input              ARREADY6_I,
   input              BUSER6_I,
   output [31 : 0]    ARADDR6_O,
   output             ARVALID6_O,
   output [7:0]       ARSIZE6_O,
   
   //Arbiter bus 7
   input [G_DDR_AXI_DW - 1 : 0] RDATA7_I,
   input              RVALID7_I,
   input              ARREADY7_I,
   input              BUSER7_I,
   output [31 : 0]    ARADDR7_O,
   output             ARVALID7_O,
   output [7:0]       ARSIZE7_O,
   
   //Arbiter wbus 0
   input          AWREADY0_I,
   input          WBUSER0_I,
   output [31:0]  AWADDR0_O,
   output [7:0]   AWSIZE0_O,
   output         AWVALID0_O,
   output [G_DDR_AXI_DW-1:0] WDATA0_O,
   output         WVALID0_O,
   
   //Arbiter wbus 1
   input          AWREADY1_I,
   input          WBUSER1_I,
   output [31:0]  AWADDR1_O,
   output [7:0]   AWSIZE1_O,
   output         AWVALID1_O,
   output [G_DDR_AXI_DW-1:0] WDATA1_O,
   output         WVALID1_O,
   
   //Arbiter wbus 2
   input          AWREADY2_I,
   input          WBUSER2_I,
   output [31:0]  AWADDR2_O,
   output [7:0]   AWSIZE2_O,
   output         AWVALID2_O,
   output [G_DDR_AXI_DW-1:0] WDATA2_O,
   output         WVALID2_O,
   
   //Arbiter wbus 3
   input          AWREADY3_I,
   input          WBUSER3_I,
   output [31:0]  AWADDR3_O,
   output [7:0]   AWSIZE3_O,
   output         AWVALID3_O,
   output [G_DDR_AXI_DW-1:0] WDATA3_O,
   output         WVALID3_O,
   
   //output data
   output [7:0]       DDR_RECON_ADDR0_O,
   output [7:0]       DDR_RECON_ADDR1_O,
   output [7:0]       DDR_RECON_ADDR2_O,
   output [7:0]       DDR_RECON_ADDR3_O,
   output             DATA0_VALID_O,
   output [15:0]      DATA0_O,
   output             DATA1_VALID_O,
   output [15:0]      DATA1_O,
   output             DATA2_VALID_O,
   output [15:0]      DATA2_O,
   output             DATA3_VALID_O,
   output [15:0]      DATA3_O,
   
   output reg         FRAME_START_O,
   
   //******************** AXI4Lite ports ****************//
   input wire 	                    ACLK_I,
   input wire 	                    ARESETN_I, 
   //write address channel
   input   	                        AWVALID_I                       ,  
   output  	                        AWREADY_O                       , 
   input   [31                 : 0] AWADDR_I                        ,
   //write data channel
   input   [31                 : 0] WDATA_I                         , 
   input   	                        WVALID_I                        , 
   output  	                        WREADY_O                        , 
   //write response channel
   output  [1                  : 0] BRESP_O                         , 
   output  	                        BVALID_O                        , 
   input   	                        BREADY_I                        ,
   //read address channel
   input   [31                 : 0] ARADDR_I                        , 
   input   	                        ARVALID_I                       , 
   output  	                        ARREADY_O                       , 
   //read data and response channel
   input   	                        RREADY_I                        , 
   output  [31                 : 0] RDATA_O                         , 
   output  [1                  : 0] RRESP_O                         , 
   output    	                    RVALID_O                             
 );

